window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["airtable"]={html:"<div class=\"own-airtable\">\n  <header class=\"at-nav\">\n    <a class=\"at-brand\" href=\"#at-top\">Northwind</a>\n    <nav class=\"at-menu\" aria-label=\"Primary\">\n      <a href=\"#at-demo\">Platform</a>\n      <a href=\"#at-sig\">Solutions</a>\n      <a href=\"#at-price\">Pricing</a>\n      <a href=\"#at-demo\">Enterprise</a>\n    </nav>\n    <div class=\"at-nav-right\">\n      <a class=\"at-navlink\" href=\"#\">Book a demo</a>\n      <a class=\"at-navlink\" href=\"#\">Log in</a>\n      <a class=\"at-btn at-btn-primary at-btn-sm\" href=\"#\">Sign up free</a>\n    </div>\n  </header>\n\n  <main id=\"at-top\">\n    <section class=\"at-hero\" aria-labelledby=\"at-h1\">\n      <h1 id=\"at-h1\" class=\"at-h1\">Production operations in prototype speed</h1>\n      <p class=\"at-hero-sub\">Northwind turns raw line, port, and fulfilment data into governed boards your whole floor can read — no export step, no stale mirror.</p>\n      <div class=\"at-hero-cta\">\n        <a class=\"at-btn at-btn-primary\" href=\"#\">Get started for free</a>\n        <a class=\"at-btn at-btn-secondary\" href=\"#\">Book a demo</a>\n      </div>\n    </section>\n\n    <section class=\"at-logos\" aria-label=\"Teams running Northwind\">\n      <p class=\"at-logos-label\">Trusted by operations teams at</p>\n      <div class=\"at-logo-row\">\n        <span class=\"at-logo\">Harborline</span>\n        <span class=\"at-logo\">Fielding</span>\n        <span class=\"at-logo\">Meridian</span>\n        <span class=\"at-logo\">Baseline</span>\n        <span class=\"at-logo\">Courier</span>\n        <span class=\"at-logo\">Northgate</span>\n      </div>\n    </section>\n\n    <section id=\"at-sig\" class=\"at-signature\" aria-labelledby=\"at-sig-h\">\n      <div class=\"at-sig-copy\">\n        <h2 id=\"at-sig-h\" class=\"at-sig-title\">The path to 10× every operator on your floor</h2>\n        <p class=\"at-sig-body\">Signature boards carry the number that matters, resolved against one governed model. Region splits, line yield, and cost per unit update together, so two shifts never argue about whose sheet is right.</p>\n        <a class=\"at-btn at-btn-secondary\" href=\"#\">See how it works</a>\n      </div>\n      <div class=\"at-sig-figure\" aria-hidden=\"true\">\n        <div class=\"at-sig-frame\">\n          <span class=\"at-sig-bar\" style=\"height:38%\"></span>\n          <span class=\"at-sig-bar\" style=\"height:62%\"></span>\n          <span class=\"at-sig-bar\" style=\"height:48%\"></span>\n          <span class=\"at-sig-bar\" style=\"height:84%\"></span>\n          <span class=\"at-sig-bar\" style=\"height:70%\"></span>\n          <span class=\"at-sig-bar\" style=\"height:96%\"></span>\n        </div>\n        <div class=\"at-sig-stat\"><b>98.1%</b><span>on-time, this quarter</span></div>\n      </div>\n    </section>\n\n    <section id=\"at-demo\" class=\"at-band\" aria-labelledby=\"at-demo-h\">\n      <div class=\"at-band-head\">\n        <p class=\"at-eyebrow\">Boards</p>\n        <h2 id=\"at-demo-h\" class=\"at-h2\">One board, every region's real number</h2>\n        <p class=\"at-band-sub\">Uneven cards on purpose — each one is a live fragment of the operations floor, not a spec sheet.</p>\n      </div>\n      <div class=\"at-demo-grid\">\n        <article class=\"at-demo at-span2\" style=\"--fill:#181d26;--ink:#ffffff\">\n          <p class=\"at-demo-eyebrow\">Live throughput</p>\n          <h3 class=\"at-demo-title\">Luzon assembly, 14-day pulse</h3>\n          <svg class=\"at-spark\" viewBox=\"0 0 320 90\" preserveAspectRatio=\"none\" aria-hidden=\"true\">\n            <polyline points=\"0,70 40,58 80,64 120,40 160,44 200,26 240,32 280,16 320,20\" fill=\"none\" stroke=\"#f4d35e\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>\n          </svg>\n        </article>\n        <article class=\"at-demo\" style=\"--fill:#aa2d00;--ink:#ffffff\">\n          <p class=\"at-demo-num\">6 lines</p>\n          <p class=\"at-demo-label\">running above grade</p>\n        </article>\n        <article class=\"at-demo\" style=\"--fill:#fcab79;--ink:#181d26\">\n          <p class=\"at-demo-eyebrow\">Yield watch</p>\n          <div class=\"at-mini-rows\">\n            <span><b>Line 3</b><em>94.6%</em></span>\n            <span><b>Line 6</b><em>97.2%</em></span>\n            <span><b>Line 9</b><em>91.8%</em></span>\n          </div>\n        </article>\n        <article class=\"at-demo at-tall\" style=\"--fill:#a8d8c4;--ink:#181d26\">\n          <p class=\"at-demo-eyebrow\">Cost per unit</p>\n          <p class=\"at-demo-num at-num-dark\">$2.41</p>\n          <p class=\"at-demo-label at-label-dark\">down 8.3% vs last quarter</p>\n          <div class=\"at-meter\"><span style=\"width:64%\"></span></div>\n        </article>\n        <article class=\"at-demo\" style=\"--fill:#f5e9d4;--ink:#181d26\">\n          <p class=\"at-demo-eyebrow\">Coverage</p>\n          <p class=\"at-demo-big at-num-dark\">12</p>\n          <p class=\"at-demo-label at-label-dark\">regions on one board</p>\n        </article>\n        <article class=\"at-demo\" style=\"--fill:#0a2e0e;--ink:#ffffff\">\n          <p class=\"at-demo-eyebrow\">Guardrail</p>\n          <p class=\"at-demo-title2\">Flags a line the moment it drifts below grade.</p>\n        </article>\n        <article class=\"at-demo at-span2\" style=\"--fill:#f8fafc;--ink:#181d26\">\n          <p class=\"at-demo-eyebrow\">Scheduled digest</p>\n          <div class=\"at-table\">\n            <span class=\"at-th\">Region</span><span class=\"at-th\">Throughput</span><span class=\"at-th\">Δ 24h</span>\n            <span>Busan</span><span>412k units</span><span class=\"at-up\">+2.1%</span>\n            <span>Sydney</span><span>287k units</span><span class=\"at-down\">−0.8%</span>\n            <span>Rotterdam</span><span>198k units</span><span class=\"at-up\">+1.4%</span>\n          </div>\n        </article>\n      </div>\n    </section>\n\n    <section class=\"at-feature\" aria-labelledby=\"at-feat-h\">\n      <div class=\"at-feature-copy\">\n        <h2 id=\"at-feat-h\" class=\"at-h2\">Everything on the floor, one source of truth</h2>\n        <ul class=\"at-checklist\">\n          <li>Region, line, and shift views from a single governed model</li>\n          <li>Live KPI rows that refresh without a manual export</li>\n          <li>Yield and cost guardrails that flag drift in the same hour</li>\n          <li>Scheduled digests straight to the ops desk inbox</li>\n        </ul>\n      </div>\n      <div class=\"at-cream\" aria-hidden=\"true\">\n        <p class=\"at-cream-kicker\">This quarter</p>\n        <p class=\"at-cream-num\">$429,423</p>\n        <p class=\"at-cream-label\">value recovered across regions</p>\n      </div>\n    </section>\n\n    <section id=\"at-price\" class=\"at-pricing\" aria-labelledby=\"at-price-h\">\n      <h2 id=\"at-price-h\" class=\"at-price-h\">Plans for every floor</h2>\n      <div class=\"at-tiers\">\n        <article class=\"at-tier\">\n          <h3 class=\"at-tier-name\">Team</h3>\n          <p class=\"at-tier-price\">$0<small>/mo</small></p>\n          <p class=\"at-tier-note\">For a single line or site.</p>\n          <ul class=\"at-tier-list\"><li>3 boards</li><li>2 regions</li><li>CSV export</li></ul>\n          <button class=\"at-btn at-btn-pill\" type=\"button\">Get started</button>\n        </article>\n        <article class=\"at-tier at-tier-featured\">\n          <h3 class=\"at-tier-name\">Business</h3>\n          <p class=\"at-tier-price\">$20<small>/seat</small></p>\n          <p class=\"at-tier-note\">For multi-site operations.</p>\n          <ul class=\"at-tier-list\"><li>Unlimited boards</li><li>12 regions</li><li>Scheduled digests</li></ul>\n          <button class=\"at-btn at-btn-pill\" type=\"button\">Start free trial</button>\n        </article>\n        <article class=\"at-tier\">\n          <h3 class=\"at-tier-name\">Enterprise</h3>\n          <p class=\"at-tier-price\">Custom</p>\n          <p class=\"at-tier-note\">For governed, multi-region floors.</p>\n          <ul class=\"at-tier-list\"><li>SSO + audit log</li><li>Unlimited regions</li><li>Named ops engineer</li></ul>\n          <button class=\"at-btn at-btn-pill\" type=\"button\">Contact sales</button>\n        </article>\n      </div>\n    </section>\n\n    <section class=\"at-cta-dark\" aria-labelledby=\"at-cta-h\">\n      <h2 id=\"at-cta-h\" class=\"at-cta-h\">Bring every region onto one governed board</h2>\n      <a class=\"at-btn at-btn-secondary\" href=\"#\">Start free trial</a>\n    </section>\n\n    <section class=\"at-cta-light\" aria-labelledby=\"at-cta2-h\">\n      <h2 id=\"at-cta2-h\" class=\"at-cta2-h\">Start building with Northwind</h2>\n      <a class=\"at-btn at-btn-primary\" href=\"#\">Get started for free</a>\n    </section>\n  </main>\n\n  <footer class=\"at-footer\">\n    <div class=\"at-foot-cols\">\n      <div class=\"at-foot-col\"><h3>Platform</h3><a href=\"#\">Boards</a><a href=\"#\">Regions</a><a href=\"#\">Guardrails</a></div>\n      <div class=\"at-foot-col\"><h3>Solutions</h3><a href=\"#\">Manufacturing</a><a href=\"#\">Logistics</a><a href=\"#\">Agri ops</a></div>\n      <div class=\"at-foot-col\"><h3>Resources</h3><a href=\"#\">Guides</a><a href=\"#\">API docs</a><a href=\"#\">Status</a></div>\n      <div class=\"at-foot-col\"><h3>Company</h3><a href=\"#\">About</a><a href=\"#\">Careers</a><a href=\"#\">Contact</a></div>\n    </div>\n    <div class=\"at-legal\">\n      <span>© 2026 Northwind Analytics — sample data, showcase only</span>\n      <span class=\"at-legal-links\"><a href=\"#\">Privacy</a><a href=\"#\">Terms</a><a href=\"#\">Cookies</a></span>\n    </div>\n  </footer>\n</div>\n",css:"/* ══ NORTHWIND — in the Airtable design language, for showcase.html ══════════\n   White canvas, near-black pill primary, editorial Haas-weight type (Inter\n   substitute), full-bleed signature coral/forest/dark cards, uneven demo grid,\n   cream callouts, and a pricing sub-system in Inter Display + pill buttons. */\n\n.own-airtable {\n  --primary: #181d26;\n  --primary-active: #0d1218;\n  --ink: #181d26;\n  --body: #333840;\n  --muted: #41454d;\n  --hairline: #dddddd;\n  --border-strong: #9297a0;\n  --canvas: #ffffff;\n  --surface-soft: #f8fafc;\n  --surface-strong: #e0e2e6;\n  --surface-dark: #181d26;\n  --signature-coral: #aa2d00;\n  --signature-forest: #0a2e0e;\n  --signature-cream: #f5e9d4;\n  --signature-peach: #fcab79;\n  --signature-mint: #a8d8c4;\n  --signature-yellow: #f4d35e;\n  --link: #1b61c9;\n  --info-border: #458fff;\n  --success: #006400;\n  --r-xs: 2px;\n  --r-sm: 6px;\n  --r-md: 10px;\n  --r-lg: 12px;\n  --r-pill: 9999px;\n  --font: 'Inter', 'Haas Groot Disp', Haas, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;\n  --font-display: 'Inter Display', 'Inter', system-ui, sans-serif;\n  --gut: clamp(24px, 5cqi, 80px);\n  --section: clamp(56px, 7cqi, 96px);\n\n  position: relative;\n  background: var(--canvas);\n  color: var(--ink);\n  font-family: var(--font);\n  font-size: 14px;\n  line-height: 1.35;\n  text-align: left;\n  border-radius: 13px;\n  overflow-x: clip;\n}\n.own-airtable *, .own-airtable *::before, .own-airtable *::after { box-sizing: border-box; }\n.own-airtable a { color: inherit; text-decoration: none; }\n.own-airtable button { font: inherit; cursor: pointer; }\n.own-airtable :focus-visible { outline: 2px solid var(--info-border); outline-offset: 2px; border-radius: 4px; }\n\n/* ── buttons ──────────────────────────────────────────────────────────────── */\n.own-airtable .at-btn { display: inline-flex; align-items: center; justify-content: center; padding: 16px 24px; border: 1px solid transparent; border-radius: var(--r-lg); font-size: 16px; font-weight: 500; line-height: 1.4; }\n.own-airtable .at-btn-sm { padding: 10px 16px; font-size: 14px; }\n.own-airtable .at-btn-primary { background: var(--primary); color: #fff; }\n.own-airtable .at-btn-primary:hover { background: var(--primary-active); }\n.own-airtable .at-btn-secondary { background: var(--canvas); color: var(--ink); border-color: var(--hairline); }\n.own-airtable .at-btn-secondary:hover { border-color: var(--border-strong); }\n.own-airtable .at-btn-pill { background: var(--canvas); color: #1d1f25; border-color: var(--border-strong); border-radius: var(--r-pill); padding: 12px 24px; }\n.own-airtable .at-btn-pill:hover { border-color: var(--ink); }\n\n/* ── top nav (64px) ───────────────────────────────────────────────────────── */\n.own-airtable .at-nav { position: sticky; top: 68px; z-index: 30; display: flex; align-items: center; gap: 28px; height: 64px; padding: 0 var(--gut); background: var(--canvas); border-bottom: 1px solid var(--hairline); }\n.own-airtable .at-brand { font-size: 22px; font-weight: 500; letter-spacing: -.01em; }\n.own-airtable .at-menu { display: flex; gap: 22px; font-size: 14px; color: var(--body); }\n.own-airtable .at-menu a:hover { color: var(--ink); }\n.own-airtable .at-nav-right { display: flex; align-items: center; gap: 18px; margin-left: auto; }\n.own-airtable .at-navlink { font-size: 14px; color: var(--body); }\n.own-airtable .at-navlink:hover { color: var(--ink); }\n\n/* ── hero (calm white canvas, no gradient) ────────────────────────────────── */\n.own-airtable .at-hero { max-width: 1280px; margin: 0 auto; padding: var(--section) var(--gut) calc(var(--section) * .6); text-align: center; }\n.own-airtable .at-h1 { font-family: var(--font); font-size: clamp(34px, 5.2cqi, 40px); font-weight: 400; line-height: 1.2; max-width: 20ch; margin: 0 auto; }\n.own-airtable .at-hero-sub { font-size: 16px; color: var(--body); line-height: 1.5; max-width: 60ch; margin: 22px auto 32px; }\n.own-airtable .at-hero-cta { display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; }\n\n/* ── logo strip ───────────────────────────────────────────────────────────── */\n.own-airtable .at-logos { padding: 40px var(--gut); border-top: 1px solid var(--hairline); border-bottom: 1px solid var(--hairline); }\n.own-airtable .at-logos-label { text-align: center; font-size: 14px; font-weight: 500; letter-spacing: .16px; color: var(--muted); margin-bottom: 22px; }\n.own-airtable .at-logo-row { display: flex; align-items: center; justify-content: center; gap: clamp(24px, 4cqi, 56px); flex-wrap: wrap; }\n.own-airtable .at-logo { font-size: 18px; font-weight: 500; color: var(--muted); letter-spacing: .02em; }\n\n/* ── signature coral card ─────────────────────────────────────────────────── */\n.own-airtable .at-signature {\n  display: grid; grid-template-columns: 1.1fr .9fr; gap: 48px; align-items: center;\n  margin: var(--section) var(--gut) 0; padding: 48px; border-radius: var(--r-lg);\n  background: var(--signature-coral); color: #fff;\n}\n.own-airtable .at-sig-title { font-size: clamp(26px, 3.4cqi, 32px); font-weight: 400; line-height: 1.2; }\n.own-airtable .at-sig-body { font-size: 14px; line-height: 1.6; margin: 18px 0 28px; max-width: 46ch; color: rgba(255, 255, 255, .9); }\n.own-airtable .at-sig-figure { display: grid; gap: 20px; }\n.own-airtable .at-sig-frame { display: flex; align-items: flex-end; gap: 12px; height: 180px; padding: 20px; border-radius: var(--r-md); background: rgba(0, 0, 0, .22); }\n.own-airtable .at-sig-bar { flex: 1; border-radius: 4px 4px 0 0; background: rgba(255, 255, 255, .85); }\n.own-airtable .at-sig-stat { display: grid; }\n.own-airtable .at-sig-stat b { font-size: 40px; font-weight: 700; line-height: 1; }\n.own-airtable .at-sig-stat span { font-size: 14px; color: rgba(255, 255, 255, .85); margin-top: 4px; }\n\n/* ── demo band ────────────────────────────────────────────────────────────── */\n.own-airtable .at-band { max-width: 1280px; margin: 0 auto; padding: var(--section) var(--gut) 0; }\n.own-airtable .at-band-head { margin-bottom: 36px; max-width: 60ch; }\n.own-airtable .at-eyebrow { font-size: 14px; font-weight: 500; letter-spacing: .16px; color: var(--muted); margin-bottom: 10px; }\n.own-airtable .at-h2 { font-size: clamp(28px, 3.8cqi, 32px); font-weight: 400; line-height: 1.2; }\n.own-airtable .at-band-sub { font-size: 14px; color: var(--body); line-height: 1.6; margin-top: 14px; }\n.own-airtable .at-demo-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; align-items: start; }\n.own-airtable .at-demo { display: grid; gap: 10px; padding: 24px; border-radius: var(--r-md); background: var(--fill, var(--canvas)); color: var(--ink, var(--ink)); align-content: start; min-height: 160px; }\n.own-airtable .at-demo[style*=\"--ink:#ffffff\"] { color: #fff; }\n.own-airtable .at-span2 { grid-column: span 2; }\n.own-airtable .at-tall { min-height: 240px; }\n.own-airtable .at-demo-eyebrow { font-size: 12px; font-weight: 500; letter-spacing: .16px; text-transform: uppercase; opacity: .7; }\n.own-airtable .at-demo-title { font-size: 20px; font-weight: 400; line-height: 1.4; }\n.own-airtable .at-demo-title2 { font-size: 18px; font-weight: 500; line-height: 1.4; }\n.own-airtable .at-demo-num { font-size: 40px; font-weight: 700; line-height: 1; }\n.own-airtable .at-demo-big { font-size: 44px; font-weight: 700; line-height: 1; }\n.own-airtable .at-demo-label { font-size: 14px; font-weight: 500; opacity: .8; }\n.own-airtable .at-spark { width: 100%; height: 90px; margin-top: auto; }\n.own-airtable .at-mini-rows { display: grid; gap: 8px; }\n.own-airtable .at-mini-rows span { display: flex; justify-content: space-between; font-size: 14px; border-top: 1px solid rgba(0, 0, 0, .12); padding-top: 8px; }\n.own-airtable .at-mini-rows span:first-child { border-top: 0; padding-top: 0; }\n.own-airtable .at-mini-rows em { font-style: normal; font-weight: 500; }\n.own-airtable .at-num-dark { color: var(--ink); }\n.own-airtable .at-label-dark { color: var(--body); opacity: 1; }\n.own-airtable .at-meter { height: 8px; border-radius: 4px; background: rgba(0, 0, 0, .12); overflow: hidden; }\n.own-airtable .at-meter span { display: block; height: 100%; background: var(--ink); border-radius: 4px; }\n.own-airtable .at-table { display: grid; grid-template-columns: 1.2fr 1fr .7fr; gap: 8px 16px; font-size: 14px; }\n.own-airtable .at-table .at-th { font-size: 12px; font-weight: 600; letter-spacing: .16px; text-transform: uppercase; color: var(--muted); border-bottom: 1px solid var(--hairline); padding-bottom: 6px; }\n.own-airtable .at-up { color: var(--success); }\n.own-airtable .at-down { color: var(--signature-coral); }\n\n/* ── feature row ──────────────────────────────────────────────────────────── */\n.own-airtable .at-feature { max-width: 1280px; margin: 0 auto; padding: var(--section) var(--gut) 0; display: grid; grid-template-columns: 1.3fr .7fr; gap: 48px; align-items: center; }\n.own-airtable .at-checklist { list-style: none; display: grid; gap: 16px; margin-top: 22px; }\n.own-airtable .at-checklist li { position: relative; padding-left: 30px; font-size: 14px; color: var(--body); line-height: 1.6; }\n.own-airtable .at-checklist li::before { content: ''; position: absolute; left: 0; top: 3px; width: 18px; height: 18px; border-radius: 50%; background: var(--signature-mint); }\n.own-airtable .at-checklist li::after { content: ''; position: absolute; left: 6px; top: 7px; width: 5px; height: 9px; border: solid var(--signature-forest); border-width: 0 2px 2px 0; transform: rotate(45deg); }\n.own-airtable .at-cream { padding: 32px 28px; border-radius: var(--r-md); background: var(--signature-cream); display: grid; gap: 6px; }\n.own-airtable .at-cream-kicker { font-size: 12px; font-weight: 600; letter-spacing: .16px; text-transform: uppercase; color: #6b5a36; }\n.own-airtable .at-cream-num { font-family: var(--font-display); font-size: clamp(34px, 5cqi, 44.8px); font-weight: 475; line-height: 1.1; color: #1d1f25; }\n.own-airtable .at-cream-label { font-size: 14px; color: #5c4e2f; }\n\n/* ── pricing sub-system ───────────────────────────────────────────────────── */\n.own-airtable .at-pricing { max-width: 1280px; margin: 0 auto; padding: var(--section) var(--gut) 0; }\n.own-airtable .at-price-h { font-family: var(--font-display); font-size: clamp(26px, 3.6cqi, 28px); font-weight: 475; line-height: 1.2; text-align: center; margin-bottom: 40px; }\n.own-airtable .at-tiers { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; align-items: start; }\n.own-airtable .at-tier { display: grid; gap: 16px; padding: 32px; border-radius: var(--r-md); border: 1px solid var(--hairline); background: var(--canvas); align-content: start; }\n.own-airtable .at-tier-featured { background: var(--surface-soft); border-color: transparent; }\n.own-airtable .at-tier-name { font-family: var(--font-display); font-size: 20px; font-weight: 475; line-height: 1.3; }\n.own-airtable .at-tier-price { font-family: var(--font-display); font-size: clamp(34px, 5cqi, 44.8px); font-weight: 475; line-height: 1.1; }\n.own-airtable .at-tier-price small { font-size: 14px; font-weight: 400; color: var(--muted); }\n.own-airtable .at-tier-note { font-size: 14px; color: var(--body); margin-top: -6px; }\n.own-airtable .at-tier-list { list-style: none; display: grid; gap: 10px; font-size: 14px; color: var(--body); }\n.own-airtable .at-tier-list li { padding-left: 22px; position: relative; }\n.own-airtable .at-tier-list li::before { content: '✓'; position: absolute; left: 0; color: var(--success); font-weight: 700; }\n\n/* ── CTA bands ────────────────────────────────────────────────────────────── */\n.own-airtable .at-cta-dark { display: flex; align-items: center; justify-content: space-between; gap: 24px; flex-wrap: wrap; margin: var(--section) var(--gut) 0; padding: 48px; border-radius: var(--r-lg); background: var(--surface-dark); color: #fff; }\n.own-airtable .at-cta-h { font-size: clamp(24px, 3.4cqi, 32px); font-weight: 400; line-height: 1.2; max-width: 22ch; }\n.own-airtable .at-cta-light { display: flex; align-items: center; justify-content: space-between; gap: 24px; flex-wrap: wrap; margin: 24px var(--gut) 0; padding: 48px; border-radius: var(--r-lg); background: var(--surface-strong); }\n.own-airtable .at-cta2-h { font-size: clamp(24px, 3.4cqi, 32px); font-weight: 400; line-height: 1.2; }\n\n/* ── footer ───────────────────────────────────────────────────────────────── */\n.own-airtable .at-footer { margin-top: var(--section); border-top: 1px solid var(--hairline); padding: 64px var(--gut) 32px; }\n.own-airtable .at-foot-cols { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; max-width: 1280px; margin: 0 auto; }\n.own-airtable .at-foot-col { display: grid; gap: 10px; align-content: start; }\n.own-airtable .at-foot-col h3 { font-size: 14px; font-weight: 500; color: var(--ink); margin-bottom: 4px; }\n.own-airtable .at-foot-col a { font-size: 14px; color: var(--muted); }\n.own-airtable .at-foot-col a:hover { color: var(--link); }\n.own-airtable .at-legal { display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap; max-width: 1280px; margin: 40px auto 0; padding-top: 20px; border-top: 1px solid var(--hairline); font-size: 13px; color: var(--muted); }\n.own-airtable .at-legal-links { display: inline-flex; gap: 18px; }\n.own-airtable .at-legal-links a:hover { color: var(--link); }\n\n/* ── responsive ───────────────────────────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-airtable .at-menu { display: none; }\n  .own-airtable .at-signature { grid-template-columns: 1fr; gap: 32px; }\n  .own-airtable .at-demo-grid { grid-template-columns: repeat(2, 1fr); }\n  .own-airtable .at-feature { grid-template-columns: 1fr; gap: 32px; }\n  .own-airtable .at-tiers { grid-template-columns: 1fr; }\n  .own-airtable .at-foot-cols { grid-template-columns: repeat(2, 1fr); }\n}\n@container frame (max-width: 760px) {\n  .own-airtable .at-nav { top: 0; height: auto; padding: 12px 16px; gap: 12px; }\n  .own-airtable .at-nav-right .at-navlink { display: none; }\n  .own-airtable .at-hero { padding: 48px 16px 32px; }\n  .own-airtable .at-band, .own-airtable .at-feature, .own-airtable .at-pricing { padding: 48px 16px 0; }\n  .own-airtable .at-signature { margin: 48px 16px 0; padding: 28px 20px; }\n  .own-airtable .at-demo-grid { grid-template-columns: 1fr; }\n  .own-airtable .at-span2 { grid-column: auto; }\n  .own-airtable .at-cta-dark, .own-airtable .at-cta-light { margin: 48px 16px 0; padding: 28px 20px; }\n  .own-airtable .at-footer { padding: 48px 16px 24px; }\n}\n@container frame (max-width: 430px) {\n  .own-airtable .at-foot-cols { grid-template-columns: 1fr; }\n  .own-airtable .at-hero-cta .at-btn { width: 100%; }\n}\n@media (prefers-reduced-motion: reduce) {\n  .own-airtable *, .own-airtable *::before, .own-airtable *::after { transition-duration: .001ms !important; animation-duration: .001ms !important; }\n}\n"};
/* ══ NORTHWIND — Airtable-language editorial boards for showcase.html ═══════
   Registers window.OWN_LAYOUTS['airtable'].init(root). The layout is
   presentational; init wires the pricing-tier picker and returns a cleanup. */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  OWN['airtable'] = {
    init: function (root) {
      var AC = window.AbortController ? new AbortController() : null;
      var signal = AC ? AC.signal : undefined;
      function on(el, type, fn, opt) { if (!el) return; opt = Object.assign({}, opt || {}); if (signal) opt.signal = signal; el.addEventListener(type, fn, opt); }

      /* the featured tier follows the choice, so the sub-system reads as live */
      var tiers = Array.prototype.slice.call(root.querySelectorAll('.at-tier'));
      on(root.querySelector('.at-tiers'), 'click', function (e) {
        var tier = e.target.closest('.at-tier');
        if (!tier) return;
        tiers.forEach(function (t) { t.classList.toggle('at-tier-featured', t === tier); });
      });

      return function cleanup() {
        if (AC) { try { AC.abort(); } catch (e) { /* ignore */ } }
      };
    }
  };
})();
